var grid = document.getElementById('grid');
var noResults = document.getElementById('noResults');
var searchInput = document.getElementById('searchInput');
var toast = document.getElementById('toast');
function esc(s){return String(s).replace(/[&<>"']/g,function(c){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[c]})}
function render(){
  grid.innerHTML='';
  DATA.forEach(function(g){
    var card=document.createElement('div');
    card.className='group';
    card.dataset.name=g.name.toLowerCase();
    card.dataset.links=g.links.join(' ').toLowerCase();
    var html='<div class="group-head"><div class="group-emoji">'+g.emoji+'</div><div class="group-name">'+esc(g.name)+'</div><div class="group-count">'+g.links.length+'</div><div class="group-chevron">▼</div></div><div class="group-body">';
    g.links.forEach(function(l){
      html+='<a class="link" href="'+esc(l)+'" target="_blank" rel="noopener noreferrer" data-url="'+esc(l)+'"><span class="link-text">'+esc(l.replace(/^https?:\/\//,''))+'</span><button class="link-copy" title="Copy">📋</button></a>';
    });
    html+='</div>';
    card.innerHTML=html;
    card.querySelector('.group-head').addEventListener('click',function(e){
      if(e.target.closest('.link-copy'))return;
      card.classList.toggle('collapsed');
    });
    grid.appendChild(card);
  });
  var copies=document.querySelectorAll('.link-copy');
  for(var i=0;i<copies.length;i++){
    copies[i].addEventListener('click',function(e){
      e.preventDefault();e.stopPropagation();
      var url=this.closest('.link').dataset.url;var btn=this;
      try{
        navigator.clipboard.writeText(url).then(function(){
          btn.classList.add('copied');btn.textContent='✓';showToast('copied');
          setTimeout(function(){btn.classList.remove('copied');btn.textContent='📋'},1200);
        });
      }catch(err){
        var ta=document.createElement('textarea');ta.value=url;document.body.appendChild(ta);ta.select();
        try{document.execCommand('copy');showToast('copied')}catch(e2){}
        document.body.removeChild(ta);
      }
    });
  }
}
function showToast(msg){toast.textContent=msg;toast.classList.add('show');clearTimeout(showToast._t);showToast._t=setTimeout(function(){toast.classList.remove('show')},1800)}
function filter(q){
  q=q.trim().toLowerCase();var visible=false;
  var cards=document.querySelectorAll('.group');
  for(var i=0;i<cards.length;i++){
    var c=cards[i];
    var m=!q||c.dataset.name.indexOf(q)!==-1||c.dataset.links.indexOf(q)!==-1;
    c.style.display=m?'':'none';
    if(m)visible=true;
  }
  if(visible)noResults.classList.remove('show');else noResults.classList.add('show');
}
searchInput.addEventListener('input',function(e){filter(e.target.value)});
document.addEventListener('keydown',function(e){
  if(e.key==='/'&&document.activeElement!==searchInput){e.preventDefault();searchInput.focus();searchInput.select()}
});
var tabNotes=document.getElementById('tabNotes');
var tabVault=document.getElementById('tabVault');
var panelNotes=document.getElementById('panelNotes');
var panelVault=document.getElementById('panelVault');
function showTab(which){
  if(which==='notes'){
    tabNotes.classList.add('active');tabVault.classList.remove('active');
    panelNotes.classList.add('active');panelVault.classList.remove('active');
  }else{
    tabVault.classList.add('active');tabNotes.classList.remove('active');
    panelVault.classList.add('active');panelNotes.classList.remove('active');
  }
}
tabNotes.addEventListener('click',function(){showTab('notes')});
tabVault.addEventListener('click',function(){showTab('vault')});
var themeBtn=document.getElementById('themeBtn');
var saved='dark';try{saved=localStorage.getItem('theme')||'dark'}catch(e){}
document.documentElement.setAttribute('data-theme',saved);
themeBtn.textContent=saved==='dark'?'🌙':'☀️';
themeBtn.addEventListener('click',function(){
  var cur=document.documentElement.getAttribute('data-theme');
  var next=cur==='dark'?'light':'dark';
  document.documentElement.setAttribute('data-theme',next);
  try{localStorage.setItem('theme',next)}catch(e){}
  themeBtn.textContent=next==='dark'?'🌙':'☀️';
});
var lastEsc=0;
document.addEventListener('keydown',function(e){
  if(e.key==='Escape'){var now=Date.now();if(now-lastEsc<500){window.location.replace('https://classroom.google.com/')}lastEsc=now}
});
render();
